class.description:
Utilisé par la fenêtre de configuration ; disponible dans l'éditeur uniquement et non instanciable. Les membres proposés sont ceux compatibles avec le type attendu par la classe d'aperçu ([method source_hint_of]).
[codeblock]
@tool
extends EditorScript

func _run() -> void:
	print(PreviewSourceEditor.source_hint_of(&"TexturePreview")) # { "type": 24, "class_name": "Texture2D" }
[/codeblock]
